224  int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
   225      csh handle;
   226      cs_insn *all_insn;
   227      cs_detail *detail;
   228      cs_err err;
   229
   230      if (Size < 1) {
   231          // 1 byte for arch choice
   232          return 0;
   233      } else if (Size > 0x1000) {
   234          //limit input to 4kb
   235          Size = 0x1000;
   236      }
   237
   238      if (outfile == NULL) {
   239          // we compute the output
   240          outfile = fopen("/dev/null", "w");
   241          if (outfile == NULL) {
   242              return 0;
   243          }
   244      }
   245
   246      int platforms_len = sizeof(platforms)/sizeof(platforms[0]);
   247      int i = (int)Data[0] % platforms_len;
   248
   249      err = cs_open(platforms[i].arch, platforms[i].mode, &handle);
   250      if (err) {
   251          return 0;
   252      }
   253
   254      cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON);
   255
   256      uint64_t address = 0x1000;
   257      size_t count = cs_disasm(handle, Data+1, Size-1, address, 0, &all_insn);
   258
   259      if (count) {
   260          size_t j;
   261          unsigned int n;
   262
   263          for (j = 0; j < count; j++) {
   264              cs_insn *i = &(all_insn[j]);
   265              fprintf(outfile, "0x%"PRIx64":\t%s\t\t%s // insn-ID: %u, insn-mnem: %s\n",
   266                     i->address, i->mnemonic, i->op_str,
   267                     i->id, cs_insn_name(handle, i->id));
   268
   269              detail = i->detail;
   270
   271              if (detail->regs_read_count > 0) {
   272                  fprintf(outfile, "\tImplicit registers read: ");
   273                  for (n = 0; n < detail->regs_read_count; n++) {
   274                      fprintf(outfile, "%s ", cs_reg_name(handle, detail->regs_read[n]));
   275                  }
   276              }
   277
   278              if (detail->regs_write_count > 0) {
   279                  fprintf(outfile, "\tImplicit registers modified: ");
   280                  for (n = 0; n < detail->regs_write_count; n++) {
   281                      fprintf(outfile, "%s ", cs_reg_name(handle, detail->regs_write[n]));
   282                  }
   283              }
   284
   285              if (detail->groups_count > 0) {
   286                  fprintf(outfile, "\tThis instruction belongs to groups: ");
   287                  for (n = 0; n < detail->groups_count; n++) {
   288                      fprintf(outfile, "%s ", cs_group_name(handle, detail->groups[n]));
   289                  }
   290              }
   291          }
   292
   293          fprintf(outfile, "0x%"PRIx64":\n", all_insn[j-1].address + all_insn[j-1].size);
   294          cs_free(all_insn, count);
   295      }
   296
   297      cs_close(&handle);
   298
   299      return 0;
   300  }
